			if First_Sea  then
				return CFrame.new(-4939.8,  7.2,  2288.0)
			end
			if Second_Sea then
				return CFrame.new(-2809.6, 20.3, -4835.5)
			end
			if Third_Sea  then
				return CFrame.new(-16207.9, 24.6,  -218.0)
			end
			return CFrame.new(0, 50, 0)
		end
		spawn(function()
			while task.wait() do
				if AutoSeaBeast then
					pcall(function()
						local L_4267_ = nil
						for L_4268_forvar0, L_4269_forvar1 in pairs(L_3466_:GetDescendants()) do
							if L_4269_forvar1:IsA("Model")
                    and (L_4269_forvar1.Name == "Sea Beast" or L_4269_forvar1.Name == "Mini Sea Beast")
                    and L_4269_forvar1:FindFirstChild("Humanoid")
                    and L_4269_forvar1:FindFirstChild("HumanoidRootPart")
                    and L_4269_forvar1.Humanoid.Health > 0 then
								L_4267_ = L_4269_forvar1
								break
							end
						end
						if L_4267_ then
							TweenWait(CFrame.new(
                        L_4267_.HumanoidRootPart.Position.X,
                        math.max(L_4267_.HumanoidRootPart.Position.Y + 20, _MIN_Y),
                        L_4267_.HumanoidRootPart.Position.Z
                    ))
							repeat
								L_3464_.Heartbeat:wait()
								EquipTool(SelectWeapon)
								pcall(function()
									local L_4270_ = L_3462_.Character
                                and L_3462_.Character:FindFirstChild("HumanoidRootPart")
									if L_4270_ and L_4267_ and L_4267_.Parent then
										L_4270_.CFrame = CFrame.new(
                                    L_4267_.HumanoidRootPart.Position.X,
                                    math.max(L_4267_.HumanoidRootPart.Position.Y + 20, _MIN_Y),
                                    L_4267_.HumanoidRootPart.Position.Z
                                )
										L_4267_.HumanoidRootPart.CanCollide   = false
										L_4267_.HumanoidRootPart.Size         = Vector3.new(60, 60, 60)
										L_4267_.HumanoidRootPart.Transparency = 1
									end
									AutoClick()
								end)
							until not AutoSeaBeast
                        or not L_4267_.Parent
                        or L_4267_.Humanoid.Health <= 0
						else
							TweenWait(L_3588_func())
							task.wait(3)
						end
					end)
				end
			end
		end)
